package cl.bolsillo.app;
import android.content.Context;import android.graphics.*;import android.graphics.drawable.Drawable;
/** Shader-cached material. Foreground content stays sharp. */
final class GlassMaterial extends Drawable {
 final Paint paint=new Paint(3);final RectF rect=new RectF(),rim=new RectF(),inside=new RectF();final float radius;final boolean dark;final int tint,alpha,intensity,fillAlpha;Shader fill,light,edge,reflection;int opacity=255;
 GlassMaterial(Context c,int alpha,int radius,int tint){this.alpha=alpha;this.radius=Glass.dp(c,radius);this.tint=tint;dark=Glass.dark(c);intensity=Glass.intensity(c);fillAlpha=Math.min(255,Math.max(dark?165:174,alpha-(intensity==2?42:intensity==0?-12:25)));}
 @Override protected void onBoundsChange(Rect b){rect.set(0,0,b.width(),b.height());rim.set(rect);rim.inset(.8f,.8f);inside.set(rim);inside.inset(1.5f,1.5f);int base=dark?0xff151a30:0xfff8f9ff;int top=Glass.mix(base,tint,dark?.18f:.22f),bottom=Glass.mix(base,tint,dark?.06f:.09f);int a=fillAlpha;fill=new LinearGradient(0,0,b.width(),b.height(),new int[]{Glass.alpha(top,a),Glass.alpha(bottom,Math.min(255,a+15))},null,Shader.TileMode.CLAMP);light=new LinearGradient(0,0,b.width()*.9f,b.height(),new int[]{dark?0x24ffffff:0x60ffffff,0x02ffffff,0x00ffffff},new float[]{0,.38f,1},Shader.TileMode.CLAMP);edge=new LinearGradient(0,0,b.width(),b.height(),new int[]{dark?0x65ffffff:0xccffffff,Glass.alpha(tint,dark?75:60),dark?0x16ffffff:0x80ffffff,Glass.alpha(tint,dark?115:90)},new float[]{0,.32f,.68f,1},Shader.TileMode.CLAMP);reflection=new RadialGradient(b.width()*.1f,-b.height()*.3f,Math.max(1,b.width()*.9f),new int[]{dark?0x38ffffff:0xa0ffffff,0x00ffffff},null,Shader.TileMode.CLAMP);}
 public void draw(Canvas c){if(opacity==0)return;int origin=c.save();c.translate(getBounds().left,getBounds().top);paint.setStyle(Paint.Style.FILL);paint.setAlpha(opacity);paint.setShader(fill);c.drawRoundRect(rect,radius,radius,paint);if(intensity>0){paint.setShader(light);c.drawRoundRect(rect,radius,radius,paint);paint.setShader(reflection);c.drawRoundRect(rect,radius,radius,paint);}paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(intensity==0?1:1.3f);paint.setShader(edge);c.drawRoundRect(rim,radius,radius,paint);if(intensity>0){paint.setShader(null);paint.setColor(dark?0x0bffffff:0x30ffffff);paint.setAlpha(((dark?11:48)*opacity+127)/255);paint.setStrokeWidth(1);c.drawRoundRect(inside,Math.max(1,radius-2),Math.max(1,radius-2),paint);}paint.setShader(null);paint.setStyle(Paint.Style.FILL);c.restoreToCount(origin);}
 // Outline alpha promises opacity, not fade strength; translucent panes must not occlude the backdrop.
 public void getOutline(Outline o){o.setRoundRect(getBounds(),radius);o.setAlpha((fillAlpha/255f)*(opacity/255f));}
 public void setAlpha(int a){opacity=Math.max(0,Math.min(255,a));invalidateSelf();}public int getAlpha(){return opacity;}public void setColorFilter(ColorFilter f){paint.setColorFilter(f);invalidateSelf();}public int getOpacity(){return PixelFormat.TRANSLUCENT;}
}
